import { webkit } from 'playwright';
import fs from 'node:fs';
const base='https://hearframe-grand-hello-world-v4.onrender.com/ask/';
const LONG='You can begin. Ask what you can do. Change only happens when ordinary people get involved. The world is very different now.';
const result={checkedAt:new Date().toISOString(),base,steps:[],consoleErrors:[],pass:false};
async function waitText(page,selector,needle,timeout=30000){const t=Date.now();let last='';while(Date.now()-t<timeout){last=(await page.locator(selector).innerText()).trim();if(last.includes(needle))return last;if(/failed|error/i.test(last))throw Error(last);await page.waitForTimeout(100)}throw Error(`timeout ${needle}; last=${last}`)}
async function waitVideo(page,timeout=30000){const v=page.locator('.msg.bot:last-child video');await v.evaluate(el=>el.play());const t=Date.now();while(Date.now()-t<timeout){const s=await v.evaluate(el=>({t:el.currentTime,d:el.duration,ended:el.ended,paused:el.paused,rs:el.readyState,error:el.error?.code||null,src:el.currentSrc}));if(s.error)throw Error('media error '+s.error);if(s.ended||(Number.isFinite(s.d)&&s.d>0&&s.t>=Math.max(0,s.d-.05)))return s;await page.waitForTimeout(80)}throw Error('video clock timeout')}
async function json(page,path){return page.evaluate(async p=>{const r=await fetch(p+'?qa='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error(`${p} HTTP ${r.status}`);return r.json()},path)}
const b=await webkit.launch({headless:true});const c=await b.newContext({viewport:{width:1194,height:834},userAgent:'Mozilla/5.0 (iPad; CPU OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1'});const p=await c.newPage();p.on('console',m=>{if(m.type()==='error')result.consoleErrors.push(m.text())});p.on('pageerror',e=>result.consoleErrors.push('pageerror: '+e.message));try{const r=await p.goto(base+'?qa='+Date.now(),{waitUntil:'networkidle',timeout:45000});result.httpStatus=r?.status();result.title=await p.title();if(result.httpStatus!==200)throw Error('HTTP '+result.httpStatus);await waitText(p,'#status','forced word alignment active',15000);result.steps.push('page-and-corpus-ready');const corpus=await json(p,'corpus.json');if(corpus.version!=='ask-v0.3')throw Error('wrong corpus version '+corpus.version);if(!/WhisperX phoneme\/CTC forced alignment/.test(corpus.alignment||''))throw Error('forced alignment metadata missing');const refs=await json(p,'reference-video-report.json');if(refs.count!==100||refs.uniqueTitles!==100||refs.uniqueSourceUrls!==100||!refs.pass)throw Error('100-reference catalog gate failed '+JSON.stringify(refs));const idx=await json(p,'reference-index-report.json');if(!idx.pass||idx.processedReferences!==100||idx.indexedSpeechReferences<70||idx.acceptedWordOccurrences<3000||idx.uniqueWords<700)throw Error('reference index gate failed '+JSON.stringify(idx));result.catalog=refs;result.referenceIndex=idx;result.steps.push('100-reference-index-pass');async function ask(q,answer,timeout=30000){await p.locator('#input').fill(q);await p.locator('#form').evaluate(f=>f.requestSubmit());await p.locator('.msg.bot:last-child .answer').waitFor({state:'visible',timeout:10000});const text=(await p.locator('.msg.bot:last-child .answer').innerText()).trim();if(text!==answer)throw Error(`answer mismatch ${q}: ${text}`);const state=await waitVideo(p,timeout);result.steps.push(answer);return state}result.start=await ask('Can I start?','You can begin.');result.long=await ask('Give me a longer answer',LONG,35000);if(result.long.d<7)throw Error('long answer unexpectedly short '+JSON.stringify(result.long));const trace=await p.locator('.msg.bot:last-child details summary').innerText();if(!trace.includes('word timestamps'))throw Error('word timestamp trace missing');result.steps.push('long-word-trace-present');await p.locator('#input').fill('What is quantum entanglement?');await p.locator('#form').evaluate(f=>f.requestSubmit());await p.locator('.msg.bot:last-child .answer').waitFor({state:'visible',timeout:10000});const fallback=(await p.locator('.msg.bot:last-child .answer').innerText()).trim();if(!fallback.includes('do not have enough indexed speech'))throw Error('fallback missing');if(await p.locator('.msg.bot:last-child video').count())throw Error('fallback fabricated video');result.steps.push('safe-corpus-gap');if(result.consoleErrors.length)throw Error('console errors '+JSON.stringify(result.consoleErrors));result.pass=true}catch(e){result.error=String(e?.stack||e);result.finalStatus=await p.locator('#status').innerText().catch(()=>null)}finally{await b.close()}fs.writeFileSync('hearframe-grand-v4/ask/live-qa.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));if(!result.pass)process.exitCode=1;
